helpers.AppendTaskGuidance(lm, "Generate a SQL SELECT statement that answers EXACTLY the question asked. SELECT only the specific columns explicitly mentioned in the question - do not add extra columns like 'name' or 'id' unless the question specifically asks for them. Use only exact table and column names from the schema. No aliases. Output: SQL: <<query>>");

var steps: nat := 0;

// Phase 1: Preamble - UnconstrainedChunk lets model emit "SQL: <<" naturally,
// stopping early when "<<" appears.
if !insideConstrainedOut && steps < maxSteps {
  var chunkBudget: nat := if maxSteps - steps <= 8 then maxSteps - steps else 8;
  var generatedOut, stoppedOnOpenSpan, stoppedOnEos, stepsUsed :=
    helpers.UnconstrainedChunk(lm, prompt, generated, chunkBudget, "<<", eosToken);
  generated := generatedOut;
  steps := steps + stepsUsed;
  if stoppedOnOpenSpan {
    var og, oi, oc := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := og;
    insideConstrainedOut := oi;
    currentConstrainedOut := oc;
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Schema-grounded SQL generation via RegenerateUnitOnGroundingFailure
// Budget capped at 300 steps (identical to attempt 66 best) to prevent runaway
// repetition loops while covering the full Spider query distribution.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  if remaining >= 2 {
    var sqlBudget: nat;
    if remaining - 1 <= 300 {
      sqlBudget := remaining - 1;
    } else {
      sqlBudget := 300;
    }
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, sqlBudget, 5, 50
    );
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    generated := stablePrefix + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + sqlBudget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 120 {
      closeBudget := remaining;
    } else {
      closeBudget := 120;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

